170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
173	        Collection<Owner> owners;
174	        if (lastName != null) {
175	            owners = this.clinicService.findOwnerByLastName(lastName);
176	        } else {
177	            owners = this.clinicService.findAllOwners();
178	        }
179	        if (owners.isEmpty()) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
198	        HttpHeaders headers = new HttpHeaders();
199	        String idempotencyKey = currentIdempotencyKey();
200	        if (idempotencyKey != null) {
201	            Integer existingId = idempotentCreates.get(idempotencyKey);
202	            if (existingId != null) {
203	                Owner existing = this.clinicService.findOwnerById(existingId);
204	                if (existing != null) {
205	                    // Repeat of a create already performed under this key: return the original
206	                    // owner with 200 instead of creating a duplicate.
207	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
208	                }
209	            }
210	        }
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        LocalDate suppliedDate = owner.getRegistrationDate();
213	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
214	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
215	                "The registration date must not be in the future");
216	        }
217	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
218	        LocalDate registrationDate = toBusinessDay(effectiveDate);
219	        owner.setRegistrationDate(registrationDate);
220	        long createdToday = this.clinicService.findAllOwners().stream()
221	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
222	            .count();
223	        if (createdToday >= 100) {
224	            throw new RestRejectionException(HttpStatus.TOO_MANY_REQUESTS,
225	                "The daily owner registration limit has been reached");
226	        }
227	        owner.setBulkSignupWarning(createdToday > 80);
228	        if (!applyAddress(owner)) {
229	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
230	                "A valid address is required");
231	        }
232	        String telephone = toE164(owner.getTelephone());
233	        if (telephone == null) {
234	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
235	                "The telephone number is not a valid E.164 number");
236	        }
237	        owner.setTelephone(telephone);
238	        if (owner.getEmail() != null) {
239	            String email = normalizeEmail(owner.getEmail());
240	            if (!EMAIL_PATTERN.matcher(email).matches()) {
241	                throw new RestRejectionException(HttpStatus.BAD_REQUEST,
242	                    "The email address is not valid");
243	            }
244	            if (isDisposableEmailDomain(email)) {
245	                throw new RestRejectionException(HttpStatus.BAD_REQUEST,
246	                    "The email domain is not accepted");
247	            }
248	            owner.setEmail(email);
249	        }
250	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
251	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
252	                "The postcode is not valid for the owner's city region");
253	        }
254	        String cityKey = householdKey(owner.getCity());
255	        long cityCount = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> existing.getCity() != null
257	                && cityKey.equals(householdKey(existing.getCity())))
258	            .count();
259	        if (cityCount >= 50) {
260	            throw new RestRejectionException(HttpStatus.CONFLICT,
261	                "The city has reached its owner capacity");
262	        }
263	        // Approaching-capacity warning: the city already holds 40-49 owners, just short of the
264	        // hard limit of 50. The 50+ rejection above still applies unchanged.
265	        owner.setCapacityWarning(cityCount >= 40 && cityCount < 50);
266	        // The household is keyed on (normalized last name, postcode): every owner derives the same
267	        // deterministic householdId from those two fields, so owners sharing them are the same
268	        // household. This computed id is what duplicate detection and the household size below key off.
269	        String householdId = householdId(owner);
270	        owner.setHouseholdId(householdId);
271	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
272	            .filter(existing -> !existing.getDeleted())
273	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
274	            .toList();
275	        owner.setHouseholdSize(householdMembers.size() + 1);
276	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
277	        // Duplicate detection is now the single identityKey (below): the separate household-duplicate
278	        // 409 block from the computed householdId no longer applies. Two owners sharing a last name and
279	        // postcode but with different telephones therefore have different identity keys and are admitted
280	        // as a soft match rather than rejected. The householdId and householdSize computed above still
281	        // drive household sizing and the level ceiling below.
282	        // Level ceiling: an owner admitted into an already-populated household without declaring
283	        // membership has its membership level capped at one above the household's current maximum, so
284	        // an undeclared newcomer can never outrank the household it joined. Declared members and
285	        // household founders are left uncapped. With no existing household member no cap applies.
286	        if (!householdMembers.isEmpty() && !sharesHousehold) {
287	            int maxHouseholdLevel = householdMembers.stream()
288	                .mapToInt(Owner::getMembershipLevel)
289	                .max()
290	                .orElse(0);
291	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
292	        }
293	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
294	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
295	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
296	        // telephone is part of the key, two household members with different telephones are allowed.
297	        // This still catches a full identity repeat even when it declares sharesHousehold.
298	        String identityKey = owner.getIdentityKey();
299	        boolean identityInUse = this.clinicService.findAllOwners().stream()
300	            .filter(existing -> !existing.getDeleted())
301	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
302	        if (identityInUse) {
303	            throw new RestRejectionException(HttpStatus.CONFLICT,
304	                "An owner with the same identity already exists");
305	        }
306	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
307	        // duplicate. Any other owner whose identityKey differs from an existing owner's but that shares
308	        // that owner's Soundex(last name) and postcode is flagged as a possible duplicate of the
309	        // earliest such owner. A full identity match would already have been rejected as a 409 above,
310	        // so every existing owner reaching here necessarily has a different identityKey.
311	        if (sharesHousehold) {
312	            owner.setPossibleDuplicate(false);
313	        } else {
314	            String softDuplicateLastNameSoundex = Owner.soundex(owner.getLastName());
315	            String softDuplicatePostcode = owner.getPostcode();
316	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
317	                : this.clinicService.findAllOwners().stream()
318	                    .filter(existing -> !existing.getDeleted())
319	                    .filter(existing -> softDuplicateLastNameSoundex.equals(Owner.soundex(existing.getLastName())))
320	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
321	                    .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
322	                    .min(Comparator.comparing(Owner::getId))
323	                    .orElse(null);
324	            if (possibleDuplicate != null) {
325	                owner.setPossibleDuplicate(true);
326	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
327	            } else {
328	                owner.setPossibleDuplicate(false);
329	            }
330	        }
331	        owner.setMemberId(memberId(owner));
332	        String firstNameKey = householdKey(owner.getFirstName());
333	        String namesakeLastNameKey = householdKey(owner.getLastName());
334	        long namesakeCount = this.clinicService.findAllOwners().stream()
335	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
336	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
337	            .count();
338	        owner.setNamesakeCount((int) namesakeCount);
339	        this.clinicService.saveOwner(owner);
340	        if (idempotencyKey != null) {
341	            idempotentCreates.put(idempotencyKey, owner.getId());
342	        }
343	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
344	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
345	            owner.getMembershipLevel());
346	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
347	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
348	        AUDIT.info("{}", event.toJson());
349	        // Enqueue a welcome notification for the freshly created owner, carrying the owner id and
350	        // the member id so downstream delivery can address and personalize it.
351	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
352	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
353	        headers.setLocation(UriComponentsBuilder.newInstance()
354	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
355	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
356	    }
357	
358	    /**
359	     * Validates an owner's postcode against the region derived from its city. The postcode is
360	     * optional: a {@code null} value is always accepted. When present it must fall within the
361	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
362	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
363	     * The 4-digit syntax itself is enforced upstream by bean validation.
364	     *
365	     * @param postcode the owner's postcode (may be {@code null})
366	     * @param locality the region derived from the owner's city
367	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
368	     *         within the region's range; {@code false} when it is out of range
369	     */
370	    /**
371	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
372	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
373	     *
374	     * @param city the owner's city (may be {@code null})
375	     * @return the canonical region, or {@code "UNKNOWN"}
376	     */
377	    /**
378	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
379	     * header is absent, blank, or no servlet request is bound to the current thread.
380	     *
381	     * @return the idempotency key, or {@code null}
382	     */
383	    private String currentIdempotencyKey() {
384	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
385	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
386	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
387	            if (key != null && !key.isBlank()) {
388	                return key.trim();
389	            }
390	        }
391	        return null;
392	    }
393	
394	    private String regionForCity(String city) {
395	        if (city == null) {
396	            return "UNKNOWN";
397	        }
398	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
399	    }
400	
401	    private boolean isPostcodeValidForCity(String postcode, String locality) {
402	        if (postcode == null) {
403	            return true;
404	        }
405	        int[] range = REGION_POSTCODES.get(locality);
406	        if (range == null) {
407	            return true;
408	        }
409	        int value = Integer.parseInt(postcode);
410	        return value >= range[0] && value <= range[1];
411	    }
412	
413	    /**
414	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
415	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
416	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
417	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
418	     * recognised country codes the national number (the digits after the country code) must also be
419	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
420	     * needs 10); a wrong national-number length yields {@code null}.
421	     *
422	     * @param telephone the raw telephone value (may be {@code null})
423	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
424	     *         a valid E.164 number
425	     */
426	    private String toE164(String telephone) {
427	        if (telephone == null) {
428	            return null;
429	        }
430	        String trimmed = telephone.trim();
431	        boolean hasCountryCode = trimmed.startsWith("+");
432	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
433	        if (hasCountryCode) {
434	            cleaned = cleaned.substring(1);
435	        }
436	        if (!cleaned.matches("[0-9]+")) {
437	            return null;
438	        }
439	        String digits;
440	        if (hasCountryCode) {
441	            digits = cleaned;
442	        } else {
443	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
444	            digits = "61" + national;
445	        }
446	        if (digits.length() < 8 || digits.length() > 15) {
447	            return null;
448	        }
449	        if (!hasValidNationalNumberLength(digits)) {
450	            return null;
451	        }
452	        return "+" + digits;
453	    }
454	
455	    /**
456	     * Checks the national-number length of an E.164 digit string (country code plus national
457	     * number, without the leading {@code '+'}) against its country code. When the number's country
458	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
459	     * country code must number exactly what that country requires; the longest matching country
460	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
461	     * only by the generic total-length rule).
462	     *
463	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
464	     * @return {@code true} if the national-number length is acceptable for the country code
465	     */
466	    private boolean hasValidNationalNumberLength(String digits) {
467	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
468	            .filter(entry -> digits.startsWith(entry.getKey()))
469	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
470	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
471	            .orElse(true);
472	    }
473	
474	    /**
475	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
476	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
477	     *
478	     * @param email the raw email value (must not be {@code null})
479	     * @return the trimmed, lower-cased email
480	     */
481	    private String normalizeEmail(String email) {
482	        return email.trim().toLowerCase(Locale.ROOT);
483	    }
484	
485	    /**
486	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
487	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
488	     * an email without an {@code '@'} carries no blocked domain.
489	     *
490	     * @param email the trimmed, lower-cased email
491	     * @return {@code true} when the email's domain is blocklisted
492	     */
493	    private boolean isDisposableEmailDomain(String email) {
494	        int at = email.lastIndexOf('@');
495	        if (at < 0) {
496	            return false;
497	        }
498	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
499	    }
500	
501	    /**
502	     * Applies the owner's address, preferring the structured form over the flat one. When a
503	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
504	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
505	     * non-blank {@code addressLine2} is present, by a single space and the normalized
506	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
507	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
508	     * is invalid.
509	     *
510	     * @param owner the owner whose address fields are normalized and composed in place
511	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
512	     */
513	    private boolean applyAddress(Owner owner) {
514	        String line1 = owner.getAddressLine1();
515	        if (line1 != null && !line1.isBlank()) {
516	            String normalizedLine1 = normalizeAddress(line1);
517	            owner.setAddressLine1(normalizedLine1);
518	            String composed = normalizedLine1;
519	            String line2 = owner.getAddressLine2();
520	            if (line2 != null && !line2.isBlank()) {
521	                String normalizedLine2 = normalizeAddress(line2);
522	                owner.setAddressLine2(normalizedLine2);
523	                composed = normalizedLine1 + " " + normalizedLine2;
524	            }
525	            owner.setAddress(composed);
526	            return true;
527	        }
528	        String address = normalizeAddress(owner.getAddress());
529	        if (address == null || address.isEmpty()) {
530	            return false;
531	        }
532	        owner.setAddress(address);
533	        return true;
534	    }
535	
536	    /**
537	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
538	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
539	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
540	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
541	     * normalized form, and every household comparison uses it.
542	     *
543	     * @param address the raw address value (may be {@code null})
544	     * @return the normalized address, or {@code null} if the input was {@code null}
545	     */
546	    private String normalizeAddress(String address) {
547	        if (address == null) {
548	            return null;
549	        }
550	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
551	        if (collapsed.isEmpty()) {
552	            return collapsed;
553	        }
554	        String[] tokens = collapsed.split(" ");
555	        StringBuilder sb = new StringBuilder(collapsed.length());
556	        for (int i = 0; i < tokens.length; i++) {
557	            if (i > 0) {
558	                sb.append(' ');
559	            }
560	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
561	        }
562	        return sb.toString();
563	    }
564	
565	    /**
566	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
567	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
568	     * so that owners are compared case-insensitively with collapsed whitespace.
569	     *
570	     * @param value the raw value (must not be {@code null})
571	     * @return the normalized comparison key
572	     */
573	    private String householdKey(String value) {
574	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
575	    }
576	
577	    /**
578	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
579	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
580	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
581	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
582	     * those two fields derives the identical identifier and therefore belongs to the same household.
583	     *
584	     * @param owner the owner whose household identifier is derived
585	     * @return the stable household identifier
586	     */
587	    private String householdId(Owner owner) {
588	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
589	        String key = householdKey(owner.getLastName()) + "|" + postcode;
590	        try {
591	            byte[] digest = MessageDigest.getInstance("SHA-256")
592	                .digest(key.getBytes(StandardCharsets.UTF_8));
593	            StringBuilder sb = new StringBuilder(digest.length * 2);
594	            for (byte b : digest) {
595	                sb.append(String.format("%02x", b));
596	            }
597	            return sb.substring(0, 12);
598	        }
599	        catch (java.security.NoSuchAlgorithmException e) {
600	            throw new IllegalStateException("SHA-256 not available", e);
601	        }
602	    }
603	
604	    /**
605	     * The owner's current primary identifier, the value carried by the structured
606	     * {@code OWNER_CREATED} audit event: the owner's {@link Owner#getMemberId() memberId}, the
607	     * single unified identifier that replaced the former customer code.
608	     *
609	     * @param owner the freshly created owner (with its member id already assigned)
610	     * @return the owner's current primary identifier
611	     */
612	    private String primaryIdentifier(Owner owner) {
613	        return owner.getMemberId();
614	    }
615	
616	    /**
617	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
618	     * is created. It is serialized to a compact JSON object and published to the {@code AUDIT}
619	     * logger so it can be routed and asserted independently of the diagnostic log. The
620	     * {@code memberId} field carries the owner's {@link #primaryIdentifier(Owner) current primary
621	     * identifier}, the unified member id.
622	     */
623	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
624	                                     Integer membershipLevel) {
625	
626	        private static final String EVENT = "OWNER_CREATED";
627	
628	        private String toJson() {
629	            return "{\"seq\":" + this.seq
630	                + ",\"ownerId\":" + this.ownerId
631	                + ",\"memberId\":" + quote(this.memberId)
632	                + ",\"membershipLevel\":" + this.membershipLevel
633	                + ",\"event\":\"" + EVENT + "\"}";
634	        }
635	
636	        private static String quote(String value) {
637	            if (value == null) {
638	                return "null";
639	            }
640	            String escaped = value.replace("\\", "\\\\").replace("\"", "\\\"");
641	            return "\"" + escaped + "\"";
642	        }
643	    }
644	
645	    /**
646	     * Builds the member id for a newly registered owner in the form
647	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code (the same region
648	     * derivation shared with {@link Owner#getLocality() locality}: postcode range first, falling
649	     * back to the city, or {@code 'UNKNOWN'}); {@code FY} is the 2-digit fiscal year of the
650	     * registration date (the last two digits of {@link Owner#getFiscalYear()}); {@code HASH8} is the
651	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
652	     * concatenated with the last name (the same HASH8 used by the region-and-hash identity); and
653	     * {@code CHK} is a single Luhn check digit computed over the decimal digits of
654	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). When the computed id collides with
655	     * an existing owner's member id, {@code '-<n>'} is appended using the smallest {@code n} of 2 or
656	     * more that makes the result unique, guaranteeing distinct owners always receive distinct member
657	     * ids.
658	     *
659	     * @param owner the owner whose member id is derived (with normalized telephone and registration
660	     *              date already set)
661	     * @return the assigned member id
662	     */
663	    private String memberId(Owner owner) {
664	        String region = owner.getLocality();
665	        String fiscalYear = owner.getFiscalYear();
666	        String fy = fiscalYear == null ? "00" : fiscalYear.substring(fiscalYear.length() - 2);
667	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
668	        String core = region + fy + hash8;
669	        String base = core + luhnCheckDigit(core);
670	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
671	            .map(Owner::getMemberId)
672	            .filter(id -> id != null)
673	            .collect(Collectors.toSet());
674	        if (!existingIds.contains(base)) {
675	            return base;
676	        }
677	        int n = 2;
678	        while (existingIds.contains(base + "-" + n)) {
679	            n++;
680	        }
681	        return base + "-" + n;
682	    }
683	
684	    /**
685	     * The single Luhn check digit ({@code 0}-{@code 9}) computed with the standard Luhn algorithm
686	     * over the decimal digits contained in {@code value} (non-digit characters are ignored).
687	     *
688	     * @param value the string whose decimal digits are checked
689	     * @return the Luhn check digit
690	     */
691	    private static int luhnCheckDigit(String value) {
692	        int sum = 0;
693	        boolean dbl = true;
694	        for (int i = value.length() - 1; i >= 0; i--) {
695	            char c = value.charAt(i);
696	            if (c < '0' || c > '9') {
697	                continue;
698	            }
699	            int d = c - '0';
700	            if (dbl) {
701	                d *= 2;
702	                if (d > 9) {
703	                    d -= 9;
704	                }
705	            }
706	            sum += d;
707	            dbl = !dbl;
708	        }
709	        return (10 - (sum % 10)) % 10;
710	    }
711	
712	    /**
713	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
714	     * UTF-8 bytes of {@code input}.
715	     *
716	     * @param input  the value to hash
717	     * @param length the number of leading hex characters to keep
718	     * @return the truncated, upper-cased hex digest
719	     */
720	    private String sha256UpperHex(String input, int length) {
721	        try {
722	            byte[] digest = MessageDigest.getInstance("SHA-256")
723	                .digest(input.getBytes(StandardCharsets.UTF_8));
724	            StringBuilder sb = new StringBuilder(digest.length * 2);
725	            for (byte b : digest) {
726	                sb.append(String.format("%02x", b));
727	            }
728	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
729	        }
730	        catch (java.security.NoSuchAlgorithmException e) {
731	            throw new IllegalStateException("SHA-256 not available", e);
732	        }
733	    }
734	
735	    /** Fixed public holidays that the business-day roll skips. */
736	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
737	        LocalDate.parse("2026-01-01"),
738	        LocalDate.parse("2026-01-26"),
739	        LocalDate.parse("2026-04-25"),
740	        LocalDate.parse("2026-12-25"),
741	        LocalDate.parse("2026-12-28"));
742	
743	    /**
744	     * Rolls a registration date forward onto a business day. When the given date falls on a
745	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
746	     * lands on a non-holiday weekday; a business day is returned unchanged.
747	     *
748	     * @param date the effective registration date (must not be {@code null})
749	     * @return the same date if it is already a business day, otherwise the next business day
750	     */
751	    private LocalDate toBusinessDay(LocalDate date) {
752	        while (isNonBusinessDay(date)) {
753	            date = date.plusDays(1);
754	        }
755	        return date;
756	    }
757	
758	    private boolean isNonBusinessDay(LocalDate date) {
759	        DayOfWeek dayOfWeek = date.getDayOfWeek();
760	        return dayOfWeek == DayOfWeek.SATURDAY
761	            || dayOfWeek == DayOfWeek.SUNDAY
762	            || PUBLIC_HOLIDAYS.contains(date);
763	    }
764	
765	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
766	    @Override
767	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
768	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
769	        if (currentOwner == null) {
770	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
771	        }
772	        String email = ownerFieldsDto.getEmail();
773	        if (email != null) {
774	            email = normalizeEmail(email);
775	            if (!EMAIL_PATTERN.matcher(email).matches()) {
776	                throw new RestRejectionException(HttpStatus.BAD_REQUEST,
777	                    "The email address is not valid");
778	            }
779	        }
780	        String telephone = toE164(ownerFieldsDto.getTelephone());
781	        if (telephone == null) {
782	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
783	                "The telephone number is not a valid E.164 number");
784	        }
785	        currentOwner.setAddress(ownerFieldsDto.getAddress());
786	        currentOwner.setCity(ownerFieldsDto.getCity());
787	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
788	        currentOwner.setLastName(ownerFieldsDto.getLastName());
789	        currentOwner.setTelephone(telephone);
790	        currentOwner.setEmail(email);
791	        this.clinicService.saveOwner(currentOwner);
792	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
793	    }
794	
795	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
796	    @Transactional
797	    @Override
798	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
799	        Owner owner = this.clinicService.findOwnerById(ownerId);
800	        if (owner == null) {
801	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
802	        }
803	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
804	        owner.setDeleted(true);
805	        this.clinicService.saveOwner(owner);
806	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
807	    }
808	
809	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
810	    @Override
811	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
812	        Owner owner = this.clinicService.findOwnerById(ownerId);
813	        if (owner == null) {
814	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
815	        }
816	        HttpHeaders headers = new HttpHeaders();
817	        Pet pet = petMapper.toPet(petFieldsDto);
818	        owner.setId(ownerId);
819	        pet.setOwner(owner);
820	        pet.getType().setName(null);
821	        this.clinicService.savePet(pet);
822	        PetDto petDto = petMapper.toPetDto(pet);
823	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
824	            .buildAndExpand(pet.getId()).toUri());
825	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
826	    }
827	
828	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
829	    @Override
830	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
831	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
832	        if (currentOwner != null) {
833	            Pet currentPet = this.clinicService.findPetById(petId);
834	            if (currentPet != null) {
835	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
836	                currentPet.setName(petFieldsDto.getName());
837	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
838	                this.clinicService.savePet(currentPet);
839	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
840	            }
841	        }
842	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
843	    }
844	
845	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
846	    @Override
847	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
848	        HttpHeaders headers = new HttpHeaders();
849	        Visit visit = visitMapper.toVisit(visitFieldsDto);
850	        Pet pet = new Pet();
851	        pet.setId(petId);
852	        visit.setPet(pet);
853	        this.clinicService.saveVisit(visit);
854	        VisitDto visitDto = visitMapper.toVisitDto(visit);
855	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
856	            .buildAndExpand(visit.getId()).toUri());
857	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
858	    }
859	
860	
861	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
862	    @Override
863	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
864	        Owner owner = this.clinicService.findOwnerById(ownerId);
865	        if (owner != null) {
866	            Pet pet = owner.getPet(petId);
867	            if (pet != null) {
868	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
869	            }
870	        }
871	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
872	    }
