333	        this.capacityWarning = capacityWarning;
334	    }
335	
336	    /**
337	     * The number of owners in this owner's household (owners sharing the same
338	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
339	     * membership tier.
340	     *
341	     * @return the household member count, or {@code null} if it has not been assigned
342	     */
343	    public Integer getHouseholdSize() {
344	        return this.householdSize;
345	    }
346	
347	    public void setHouseholdSize(Integer householdSize) {
348	        this.householdSize = householdSize;
349	    }
350	
351	    /**
352	     * The upper bound applied to this owner's {@link #getMembershipLevel() membership level}: one
353	     * above the highest membership level held by their household members at the time this owner was
354	     * created. It is assigned only to an owner admitted into an already-populated household, and is
355	     * {@code null} (no cap) for a household founder or a declared household member, so their level is
356	     * not restricted.
357	     *
358	     * @return the membership-level cap, or {@code null} when no cap applies
359	     */
360	    public Integer getMembershipLevelCap() {
361	        return this.membershipLevelCap;
362	    }
363	
364	    public void setMembershipLevelCap(Integer membershipLevelCap) {
365	        this.membershipLevelCap = membershipLevelCap;
366	    }
367	
368	    /**
369	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
370	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
371	     *
372	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
373	     *         {@code false} (never {@code null})
374	     */
375	    public Boolean getPossibleDuplicate() {
376	        return this.possibleDuplicate != null && this.possibleDuplicate;
377	    }
378	
379	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
380	        this.possibleDuplicate = possibleDuplicate;
381	    }
382	
383	    /**
384	     * The id of the existing owner this owner may duplicate (same last name and postcode,
385	     * different telephone), or {@code null} when this owner is not a possible duplicate.
386	     *
387	     * @return the matching owner id, or {@code null}
388	     */
389	    public Integer getPossibleDuplicateOf() {
390	        return this.possibleDuplicateOf;
391	    }
392	
393	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
394	        this.possibleDuplicateOf = possibleDuplicateOf;
395	    }
396	
397	    /**
398	     * The base labels (the label before the first dot) of the known disposable email domains. An
399	     * owner's email domain is judged disposable-adjacent when its own base label is one of these,
400	     * so a near-variant of a blocklisted disposable domain under a different top-level domain
401	     * (e.g. {@code mailinator.net} for {@code mailinator.com}) still trips the risk flag.
402	     */
403	    private static final Set<String> DISPOSABLE_EMAIL_BASE_LABELS =
404	        Set.of("mailinator", "tempmail", "guerrillamail");
405	
406	    /**
407	     * Whether this owner's email domain is disposable-adjacent: the domain's base label (the label
408	     * before its first dot, e.g. {@code "mailinator"} in {@code "mailinator.net"}) matches the base
409	     * label of a known disposable domain. An owner with no email carries no disposable-adjacent
410	     * domain.
411	     *
412	     * @return {@code true} when the email domain is disposable-adjacent, otherwise {@code false}
413	     */
414	    private boolean hasDisposableAdjacentEmail() {
415	        if (this.email == null) {
416	            return false;
417	        }
418	        int at = this.email.lastIndexOf('@');
419	        if (at < 0) {
420	            return false;
421	        }
422	        String domain = this.email.substring(at + 1).toLowerCase(Locale.ROOT);
423	        int dot = domain.indexOf('.');
424	        String baseLabel = dot < 0 ? domain : domain.substring(0, dot);
425	        return DISPOSABLE_EMAIL_BASE_LABELS.contains(baseLabel);
426	    }
427	
428	    /**
429	     * Whether this owner warrants a manual risk review. It is {@code true} when any of three signals
430	     * holds: the owner is a {@link #getPossibleDuplicate() possible duplicate}, the owner's email
431	     * domain is {@link #hasDisposableAdjacentEmail() disposable-adjacent}, or the owner's city is
432	     * over its soft capacity - the same 40-owner threshold that raises the
433	     * {@link #getCapacityWarning() capacity warning}; otherwise {@code false}.
434	     *
435	     * @return {@code true} when any risk signal holds, otherwise {@code false} (never {@code null})
436	     */
437	    public Boolean getRiskFlag() {
438	        return getPossibleDuplicate() || hasDisposableAdjacentEmail() || getCapacityWarning();
439	    }
440	
441	    /**
442	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an
443	     * owner via {@code DELETE /api/owners/{id}} flags it {@code true} while retaining the record.
444	     * A deleted owner is ignored by the create endpoint's duplicate and identity checks.
445	     *
446	     * @return {@code true} when the owner has been soft-deleted, otherwise {@code false} (never
447	     *         {@code null})
448	     */
449	    public Boolean getDeleted() {
450	        return this.deleted != null && this.deleted;
451	    }
452	
453	    public void setDeleted(Boolean deleted) {
454	        this.deleted = deleted;
455	    }
456	
457	    /**
458	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
459	     *
460	     * @return the formatted display name
461	     */
462	    public String getDisplayName() {
463	        return this.getLastName() + ", " + this.getFirstName();
464	    }
465	
466	    /**
467	     * The owner's initials: the upper-cased first letters of the first and last
468	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
469	     *
470	     * @return the formatted initials
471	     */
472	    public String getInitials() {
473	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
474	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
475	    }
476	
477	    /**
478	     * The fiscal year of the (business-day-adjusted) {@link #registrationDate}, formatted as
479	     * {@code "FY<YY>"}. The fiscal year starts on 1 July: a registration date on or after 1 July
480	     * belongs to that calendar year's fiscal year, an earlier date belongs to the previous year's,
481	     * and {@code YY} is the last two digits of the year the fiscal year started (e.g. a date in
482	     * August 2026 yields {@code "FY26"}, a date in March 2026 yields {@code "FY25"}).
483	     *
484	     * @return the formatted fiscal year, or {@code null} if the registration date has not been
485	     *         assigned
486	     */
487	    public String getFiscalYear() {
488	        if (this.registrationDate == null) {
489	            return null;
490	        }
491	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
492	    }
493	
494	    /**
495	     * The starting calendar year of the fiscal year (which begins on 1 July) that the given date
496	     * falls in: the date's own year when it is on or after 1 July, otherwise the previous year.
497	     *
498	     * @param date the date whose fiscal year is derived (must not be {@code null})
499	     * @return the starting calendar year of the fiscal year
500	     */
501	    private static int fiscalYearOf(LocalDate date) {
502	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
503	            ? date.getYear() : date.getYear() - 1;
504	    }
505	
506	    /**
507	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
508	     * they carry an email address, {@code 1} when they have no namesakes
509	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
510	     * members ({@code householdSize}), and {@code 3} for tenure of at least one elapsed
511	     * fiscal year (the {@code registrationDate}'s fiscal year precedes the current fiscal
512	     * year, the fiscal year starting on 1 July). Because a newly created owner is still in
513	     * the current fiscal year, a new owner can score at most {@code 5} points.
514	     *
515	     * @return the membership points
516	     */
517	    public Integer getMembershipPoints() {
518	        int points = 0;
519	        boolean hasEmail = this.email != null && !this.email.isBlank();
520	        if (hasEmail) {
521	            points += 2;
522	        }
523	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
524	        if (noNamesakes) {
525	            points += 1;
526	        }
527	        if (this.householdSize != null && this.householdSize >= 3) {
528	            points += 2;
529	        }
530	        if (this.registrationDate != null
531	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
532	            points += 3;
533	        }
534	        return points;
535	    }
536	
537	    /**
538	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
539	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
540	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
541	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
542	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
543	     * is reserved for owners whose tenure spans at least one elapsed fiscal year.
544	     *
545	     * <p>When a {@link #getMembershipLevelCap() membership-level cap} has been assigned the
546	     * points-derived level is capped to it, so an owner admitted into an existing household can never
547	     * exceed one level above their household's highest member.
548	     *
549	     * @return the membership level
550	     */
551	    public Integer getMembershipLevel() {
552	        int level = pointsMembershipLevel();
553	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
554	            return this.membershipLevelCap;
555	        }
556	        return level;
557	    }
558	
559	    /**
560	     * The membership level derived purely from the {@link #getMembershipPoints() membership points},
561	     * before any {@link #getMembershipLevelCap() household cap} is applied.
562	     *
563	     * @return the uncapped, points-derived membership level
564	     */
565	    private int pointsMembershipLevel() {
566	        int points = getMembershipPoints();
567	        if (points >= 6) {
568	            return 4;
569	        }
570	        if (points >= 4) {
571	            return 3;
572	        }
573	        if (points >= 2) {
574	            return 2;
575	        }
576	        return 1;
577	    }
578	
579	    /**
580	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
581	     * email address, otherwise {@code "PHONE"}.
582	     *
583	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
584	     */
585	    public String getContactPreference() {
586	        boolean hasEmail = this.email != null && !this.email.isBlank();
587	        return hasEmail ? "EMAIL" : "PHONE";
588	    }
589	
590	    /**
591	     * The owner's segment, formatted {@code "<TIER>_<AREA>"}, one of {@code "PREMIUM_METRO"},
592	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. The tier
593	     * is {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is {@code 3} or
594	     * more, otherwise {@code "STANDARD"}. The area is {@code "METRO"} when the
595	     * {@link #getLocality() locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
596	     * otherwise {@code "REGIONAL"}.
597	     *
598	     * @return the formatted owner segment
599	     */
600	    public String getOwnerSegment() {
601	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
602	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
603	        return tier + "_" + area;
604	    }
605	
606	    /**
607	     * The owner's identity key: the single derived value used for duplicate detection. It is the
608	     * lower-case, 64-character hex SHA-256 digest over
609	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, where the telephone
610	     * is the already-normalized stored value, the email is lower-cased (a {@code null} email is
611	     * rendered as the empty string) and the last name is reduced to its Soundex code. Two owners are
612	     * duplicates only when their whole identity keys are equal; because the telephone is part of the
613	     * key, two owners sharing a last name (Soundex) but with different telephones have different
614	     * identity keys and so are not hard duplicates.
615	     *
616	     * @return the derived identity key
617	     */
618	    public String getIdentityKey() {
619	        String telephonePart = this.telephone == null ? "" : this.telephone;
620	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
621	        String soundexPart = soundex(getLastName());
622	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
623	    }
624	
625	    /**
626	     * Returns the lower-case, 64-character hex SHA-256 digest of the UTF-8 bytes of {@code input}.
627	     *
628	     * @param input the value to hash
629	     * @return the full hex digest
630	     */
631	    private static String sha256Hex(String input) {
632	        try {
633	            byte[] digest = MessageDigest.getInstance("SHA-256")
634	                .digest(input.getBytes(StandardCharsets.UTF_8));
635	            StringBuilder sb = new StringBuilder(digest.length * 2);
636	            for (byte b : digest) {
637	                sb.append(String.format("%02x", b));
638	            }
639	            return sb.toString();
640	        }
641	        catch (NoSuchAlgorithmException e) {
642	            throw new IllegalStateException("SHA-256 not available", e);
643	        }
644	    }
645	
646	    /**
647	     * Computes the American Soundex code of a name: the first letter followed by three digits that
648	     * phonetically encode the remaining consonants. Non-letters are ignored, {@code h} and {@code w}
649	     * are transparent (letters either side of them are treated as adjacent) and vowels reset the
650	     * run so a repeated code across a vowel is encoded twice. A {@code null} or letter-free value
651	     * yields the empty string.
652	     *
653	     * @param value the name to encode
654	     * @return the Soundex code, or the empty string when there is no letter to encode
655	     */
656	    public static String soundex(String value) {
657	        if (value == null) {
658	            return "";
659	        }
660	        StringBuilder letters = new StringBuilder();
661	        for (int i = 0; i < value.length(); i++) {
662	            char c = Character.toUpperCase(value.charAt(i));
663	            if (c >= 'A' && c <= 'Z') {
664	                letters.append(c);
665	            }
666	        }
667	        if (letters.length() == 0) {
668	            return "";
669	        }
670	        StringBuilder code = new StringBuilder();
671	        char first = letters.charAt(0);
672	        code.append(first);
673	        char last = soundexDigit(first);
674	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
675	            char c = letters.charAt(i);
676	            if (c == 'H' || c == 'W') {
677	                // Transparent: leave the previous code in place so letters either side stay adjacent.
678	                continue;
679	            }
680	            char digit = soundexDigit(c);
681	            if (digit != '0') {
682	                if (digit != last) {
683	                    code.append(digit);
684	                }
685	                last = digit;
686	            }
687	            else {
688	                // A vowel breaks the run so a following letter with the same code is encoded again.
689	                last = '0';
690	            }
691	        }
692	        while (code.length() < 4) {
693	            code.append('0');
694	        }
695	        return code.toString();
696	    }
697	
698	    /**
699	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
700	     * uncoded letters {@code h} and {@code w}.
701	     */
702	    private static char soundexDigit(char c) {
703	        switch (c) {
704	            case 'B': case 'F': case 'P': case 'V':
705	                return '1';
706	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
707	                return '2';
708	            case 'D': case 'T':
709	                return '3';
710	            case 'L':
711	                return '4';
712	            case 'M': case 'N':
713	                return '5';
714	            case 'R':
715	                return '6';
716	            default:
717	                return '0';
718	        }
719	    }
720	
721	    /**
722	     * City -> canonical region, the fixed ground truth for deriving locality.
723	     */
724	    private static final Map<String, String> CITY_REGION = Map.of(
725	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
726	
727	    /**
728	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
729	     * deriving locality from the postcode ahead of the city.
730	     */
731	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
732	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
733	
734	    /**
735	     * The owner's locality: the canonical region resolved by the postcode range first
736	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
737	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
738	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
739	     * when the city is not in the table either. The postcode takes precedence so cities that share a
740	     * name are disambiguated by their postcode's region.
741	     *
742	     * @return the canonical region string, or {@code "UNKNOWN"}
743	     */
744	    public String getLocality() {
745	        String byPostcode = regionForPostcode(this.postcode);
746	        if (byPostcode != null) {
747	            return byPostcode;
748	        }
749	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
750	    }
751	
752	    /**
753	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
754	     * its locality.
755	     */
756	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
757	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
758	
759	    /**
760	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
761	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
762	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
763	     * (e.g. {@code "UNKNOWN"}).
764	     *
765	     * @return the IANA timezone name, or {@code null}
766	     */
767	    public String getTimezone() {
768	        return REGION_TIMEZONE.get(getLocality());
769	    }
770	
771	    /**
772	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
773	     * absent, not a 4-digit number, or in no known range.
774	     *
775	     * @param postcode the owner's postcode (may be {@code null})
776	     * @return the matching region, or {@code null}
777	     */
778	    private static String regionForPostcode(String postcode) {
779	        if (postcode == null || !postcode.matches("\\d{4}")) {
780	            return null;
781	        }
782	        int value = Integer.parseInt(postcode);
783	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
784	            int[] range = entry.getValue();
785	            if (value >= range[0] && value <= range[1]) {
786	                return entry.getKey();
787	            }
788	        }
789	        return null;
790	    }
791	
792	    protected Set<Pet> getPetsInternal() {
793	        if (this.pets == null) {
794	            this.pets = new HashSet<>();
795	        }
796	        return this.pets;
797	    }
798	
799	    protected void setPetsInternal(Set<Pet> pets) {
800	        this.pets = pets;
801	    }
802	
803	    public List<Pet> getPets() {
804	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
805	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
806	        return Collections.unmodifiableList(sortedPets);
807	    }
808	
809	    public void setPets(List<Pet> pets) {
810	        this.pets = new HashSet<>(pets);
811	    }
812	
813	    public void addPet(Pet pet) {
814	        getPetsInternal().add(pet);
815	        pet.setOwner(this);
816	    }
817	
818	    /**
819	     * Return the Pet with the given name, or null if none found for this Owner.
820	     *
821	     * @param name to test
822	     * @return true if pet name is already in use
823	     */
824	    public Pet getPet(String name) {
825	        return getPet(name, false);
826	    }
827	
828	    /**
829	     * Return the Pet with the given name, or null if none found for this Owner.
830	     *
831	     * @param name to test
832	     * @return true if pet name is already in use
833	     */
834	    public Pet getPet(String name, boolean ignoreNew) {
835	        name = name.toLowerCase();
836	        for (Pet pet : getPetsInternal()) {
837	            if (!ignoreNew || !pet.isNew()) {
838	                String compName = pet.getName();
839	                compName = compName.toLowerCase();
840	                if (compName.equals(name)) {
841	                    return pet;
842	                }
843	            }
844	        }
845	        return null;
846	    }
847	
848	    public Pet getPet(Integer petId) {
849	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
850	    }
851	
852	    @Override
853	    public String toString() {
854	        return new ToStringCreator(this)
855	
856	            .append("id", this.getId())
857	            .append("new", this.isNew())
858	            .append("lastName", this.getLastName())
859	            .append("firstName", this.getFirstName())
860	            .append("address", this.address)
861	            .append("city", this.city)
862	            .append("telephone", this.telephone)
863	            .append("email", this.email)
864	            .toString();
865	    }
866	}
