    String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
    String soundexPart = soundex(getLastName());
    return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart
        + "|" + IDENTITY_VERSION_TAG);
}

